        s = draw(st.lists(st.integers(0, m), min_size=p, max_size=p))
        if sum(s) == 0:
            s[draw(st.integers(0, p - 1))] = draw(st.integers(1, m))
        lines.append(" ".join(map(str, [c, p] + s)))
    return "\n".join(lines) + "\n"


def validate(inp):
    try:
        t = list(map(int, inp.split()))
    except ValueError:
        return False
    if len(t) < 2:
        return False
    n, m = t[0], t[1]
    if not (1 <= n <= 100 and 1 <= m <= 100):
        return False
    idx = 2
    for _ in range(n):
        if idx + 2 > len(t):
            return False
        c, p = t[idx], t[idx + 1]
        if not (1 <= c <= 10 ** 4 and 1 <= p <= 100):
            return False
        idx += 2
        if idx + p > len(t):
            return False
        s = t[idx:idx + p]
        idx += p
        if not all(0 <= v <= m for v in s):
            return False
        if sum(s) <= 0:
            return False
