    n, m = t[0], t[1]
    idx = 2
    wheels = []
    for _ in range(n):
        c, p = t[idx], t[idx + 1]
        s = t[idx + 2: idx + 2 + p]
        idx += 2 + p
        wheels.append((c, s))
    E = [0.0] * (m + 1)

    def get(y):
        return 0.0 if y >= m else E[y]

    for x in range(m - 1, -1, -1):
        best = float("inf")
        for c, s in wheels:
            P = len(s)
            z = sum(1 for v in s if v == 0)
            tot = P * c + sum(get(x + v) for v in s if v > 0)
            val = tot / (P - z)
            if val < best:
                best = val
        E[x] = best
    return f"{E[0]:.10f}"


